// 6 · remind-sweep（Scheduler，每日）
// ============================================================
//
// 幂等键按契约是 `(user_id, remind_kind, day)`。库里没有提醒表，
// 于是这个键落在 email_log 上：`(user_id, template, 当天)`。
//
// 🔴 **这个去重是「建议性」的，不是数据库强制的** —— 必须说清楚，否则下一个人会以为它是。
//
//	email_log 上没有 `(user_id, template, date(created_at))` 的唯一索引，
//	所以 NOT EXISTS 与后面的 INSERT 之间有窗口：两个实例同时跑同一次 Scheduler 投递时，
//	双方都能通过检查，用户会收到两封一样的提醒。
//	接受这个代价的理由：Cloud Scheduler 对同一 job 的并发投递是异常而非常态，
//	而重复的后果是「多收一封信」，不是钱。真要根治需要一条新 migration 加部分唯一索引。
//	TODO(P2): `CREATE UNIQUE INDEX ... ON email_log (user_id, template,
//	          (created_at AT TIME ZONE 'Asia/Shanghai')::date) WHERE user_id IS NOT NULL`。
//
// 「当天」的口径用 Asia/Shanghai 切天，与 stats.sql 的 stat_date 一致 ——
// 报表与提醒用两个不同的「天」会让「昨天发了几封」这种问题永远对不上。
//
// 🔴 notify_expire / notify_traffic 是用户开关，这两条查询必须尊重它们；
//
//	但 `service_broadcast`（失联广播）**不受任何开关控制**，所以它不在本任务里 ——
//	0003_accounts.up.sql 表达这条裁决的方式就是 users 上根本没有那一列
//	（account.sql 的长注释：「用户把它关掉的那天，就是我们再也够不到他的那天」）。
//	往这里加一个「广播提醒」分支之前先读那段注释。
func (q *Queries) ListRemindableExpiringUsers(ctx context.Context, arg ListRemindableExpiringUsersParams) ([]ListRemindableExpiringUsersRow, error) {
	rows, err := q.db.Query(ctx, listRemindableExpiringUsers, arg.WithinDays, arg.Template, arg.Batch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRemindableExpiringUsersRow{}
	for rows.Next() {
		var i ListRemindableExpiringUsersRow
		if err := rows.Scan(&i.ID, &i.Email, &i.ExpiredAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listRemindableTrafficUsers = `-- name: ListRemindableTrafficUsers :many
SELECT u.id, u.email, ut.u, ut.d, u.transfer_enable
FROM users u
JOIN user_traffic ut ON ut.user_id = u.id
WHERE u.deleted_at IS NULL
  AND u.banned = false
  AND u.notify_traffic = true
  AND u.transfer_enable > 0
  AND coalesce(u.expired_at, 'infinity'::timestamptz) > now()
  AND (ut.u + ut.d) * 100 >= u.transfer_enable * $1::bigint
  AND NOT EXISTS (
    SELECT 1 FROM email_log el
    WHERE el.user_id = u.id
      AND el.template = $2::text
      AND (el.created_at AT TIME ZONE 'Asia/Shanghai')::date
          = (now()        AT TIME ZONE 'Asia/Shanghai')::date
  )
ORDER BY u.id
LIMIT $3::integer
`

type ListRemindableTrafficUsersParams struct {
	ThresholdPct int64  `json:"threshold_pct"`
	Template     string `json:"template"`
	Batch        int32  `json:"batch"`
}

type ListRemindableTrafficUsersRow struct {
	ID             int64  `json:"id"`
	Email          string `json:"email"`
	U              int64  `json:"u"`
	D              int64  `json:"d"`
	TransferEnable int64  `json:"transfer_enable"`
}

// 流量提醒。
//
// ⚠️ 阈值比较写成 `(u + d) * 100 >= transfer_enable * pct` 而不是先算百分比 ——
//
//	整数除法会把 79.9% 算成 79，于是 80% 的提醒在恰好卡线时不发。
//	溢出核算：u/d 是字节 bigint，即使 1 PB（1e15）× 100 = 1e17，
//	仍远低于 bigint 上限 9.2e18。
//
// transfer_enable > 0 是必须的：不限流量的套餐（配额 0 或未开通）恒满足任何百分比，
// 会给全部这类用户天天发「流量快用完了」。
func (q *Queries) ListRemindableTrafficUsers(ctx context.Context, arg ListRemindableTrafficUsersParams) ([]ListRemindableTrafficUsersRow, error) {
	rows, err := q.db.Query(ctx, listRemindableTrafficUsers, arg.ThresholdPct, arg.Template, arg.Batch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRemindableTrafficUsersRow{}
	for rows.Next() {
		var i ListRemindableTrafficUsersRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.U,
			&i.D,
			&i.TransferEnable,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

